     5	import type {ValueOf} from 'type-fest';
     6	import useLocalize from '@hooks/useLocalize';
     7	import useThemeStyles from '@hooks/useThemeStyles';
     8	import Navigation from '@libs/Navigation/Navigation';
     9	import CONST from '@src/CONST';
    10	import ROUTES from '@src/ROUTES';
    11	import MenuItemWithTopDescription from './MenuItemWithTopDescription';
    12	
    13	type CurrencySelectorProps = {
    14	    /** Form error text. e.g when no currency is selected */
    15	    errorText?: string;
    16	
    17	    /** Callback called when the currency changes. */
    18	    onInputChange?: (value?: string) => void;
    19	
    20	    /** Current selected currency  */
    21	    value?: ValueOf<typeof CONST.CURRENCY>;
    22	
    23	    /** inputID used by the Form component */
    24	    // eslint-disable-next-line react/no-unused-prop-types
    25	    inputID: string;
    26	
    27	    /** Callback to call when the picker modal is dismissed */
    28	    onBlur?: () => void;
    29	
    30	    /** object to get route details from */
    31	    currencySelectorRoute?: typeof ROUTES.SETTINGS_SUBSCRIPTION_CHANGE_PAYMENT_CURRENCY | typeof ROUTES.SETTINGS_CHANGE_CURRENCY;
    32	};
    33	
    34	function CurrencySelector(
    35	    {errorText = '', value: currency, onInputChange = () => {}, onBlur, currencySelectorRoute = ROUTES.SETTINGS_CHANGE_CURRENCY}: CurrencySelectorProps,
    36	    ref: ForwardedRef<View>,
    37	) {
    38	    const styles = useThemeStyles();
    39	    const {translate} = useLocalize();
    40	
    41	    const currencyTitleDescStyle = currency ? styles.textNormal : null;
    42	
    43	    const didOpenCurrencySelector = useRef(false);
    44	    const isFocused = useIsFocused();
    45	    useEffect(() => {
    46	        if (!isFocused || !didOpenCurrencySelector.current) {
    47	            return;
    48	        }
    49	        didOpenCurrencySelector.current = false;
    50	        onBlur?.();
    51	    }, [isFocused, onBlur]);
    52	
    53	    useEffect(() => {
    54	        // This will cause the form to revalidate and remove any error related to currency
    55	        onInputChange(currency);
    56	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
    57	    }, [currency]);
    58	
    59	    return (
    60	        <MenuItemWithTopDescription
    61	            shouldShowRightIcon
    62	            title={currency}
    63	            ref={ref}
    64	            descriptionTextStyle={currencyTitleDescStyle}
    65	            brickRoadIndicator={errorText ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined}
    66	            description={translate('common.currency')}
    67	            errorText={errorText}
    68	            onPress={() => {
    69	                didOpenCurrencySelector.current = true;
    70	                Navigation.navigate(currencySelectorRoute);
    71	            }}
    72	        />
    73	    );
    74	}
    75	
    76	CurrencySelector.displayName = 'CurrencySelector';
    77	
    78	export default forwardRef(CurrencySelector);
